import sys
from datetime import date, timedelta

RATE = {"book": 0.5, "dvd": 1.0, "magazine": 0.2}


def parse(text):
    y, m, d = map(int, text.split("-"))
    return date(y, m, d)


def adjust_due_date(due_date):
    due = parse(due_date)
    if due.weekday() == 6:  # Sunday
        due += timedelta(days=1)
    return due


def main():
    lines = sys.stdin.read().splitlines()
    totals = {}
    asof_date = parse(lines[0].split()[1])

    for line in lines[1:]:
        if not line.strip():
            continue
        member, kind, due_str, returned_str = line.split()
        due_date = parse(due_str)
        returned_date = parse(returned_str) if returned_str != "-" else None

        adjusted_due = adjust_due_date(due_date)

        if returned_date is None:
            return_date = asof_date
        else:
            return_date = returned_date

        days_late = (return_date - adjusted_due).days
        if days_late <= 0:
            continue

        fee = max(0, days_late - 3) * RATE[kind]
        fee = min(fee, 10.00)

        totals[member] = totals.get(member, 0.0) + fee

    for member in sorted(totals):
        print(f"{member} {totals[member]:.2f}")
    print(f"total {sum(totals.values()):.2f}")


if __name__ == "__main__":
    main()
